import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"七月","description":"","frontmatter":{"title":"七月","date":"2026-11-07T00:00:00.000Z","seq":154,"categories":["美文","诗经"],"collection":"《诗经 · 国风》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·国风/七月.md","filePath":"blogs/诗经·国风/七月.md"}'),o={name:"blogs/诗经·国风/七月.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="七月" tabindex="-1">七月 <a class="header-anchor" href="#七月" aria-label="Permalink to &quot;七月&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　豳风</p><div class="poem"><p class="poem-stanza">七月流火，九月授衣。一之日觱发，二之日栗烈。无衣无褐，何以卒岁？</p><p class="poem-stanza">三之日于耜，四之日举趾。同我妇子，馌彼南亩。田畯至喜。</p><p class="poem-stanza">七月流火，九月授衣。春日载阳，有鸣仓庚。女执懿筐，遵彼微行，爰求柔桑。</p><p class="poem-stanza">春日迟迟，采蘩祁祁。女心伤悲，殆及公子同归。</p><p class="poem-stanza">七月流火，八月萑苇。蚕月条桑，取彼斧斨。以伐远扬，猗彼女桑。</p><p class="poem-stanza">七月鸣鵙，八月载绩。载玄载黄，我朱孔阳，为公子裳。</p><p class="poem-stanza">四月秀葽，五月鸣蜩。八月其获，十月陨萚。一之日于貉，取彼狐狸，为公子裘。</p><p class="poem-stanza">二之日其同，载缵武功。言私其豵，献豜于公。</p><p class="poem-stanza">五月斯螽动股，六月莎鸡振羽。七月在野，八月在宇，九月在户，十月蟋蟀，入我床下。</p><p class="poem-stanza">穹窒熏鼠，塞向墐户。嗟我妇子，曰为改岁，入此室处。</p><p class="poem-stanza">六月食郁及薁，七月亨葵及菽。八月剥枣，十月获稻。为此春酒，以介眉寿。</p><p class="poem-stanza">七月食瓜，八月断壶，九月叔苴，采荼薪樗。食我农夫。</p><p class="poem-stanza">九月筑场圃，十月纳禾稼。黍稷重穋，禾麻菽麦。嗟我农夫，我稼既同，上入执宫功。</p><p class="poem-stanza">昼尔于茅，宵尔索綯，亟其乘屋，其始播百谷。</p><p class="poem-stanza">二之日凿冰冲冲，三之日纳于凌阴。四之日其蚤，献羔祭韭。九月肃霜，十月涤场。</p><p class="poem-stanza">朋酒斯飨，曰杀羔羊，跻彼公堂。称彼兕觥：万寿无疆！</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
